package com.rainsleep.app;
import android.app.*;import android.os.*;import android.webkit.*;import android.content.*;import android.view.*;
public class MainActivity extends Activity {
 WebView web;Handler handler=new Handler(Looper.getMainLooper());
 final WebChromeClient chrome=new WebChromeClient(){public android.graphics.Bitmap getDefaultVideoPoster(){return android.graphics.Bitmap.createBitmap(1,1,android.graphics.Bitmap.Config.ARGB_8888);}public void onShowCustomView(View view,CustomViewCallback callback){callback.onCustomViewHidden();}};
 Runnable updates=new Runnable(){public void run(){if(web!=null)web.evaluateJavascript("window.nativeState&&window.nativeState({playing:"+RainService.playing+",deadline:"+RainService.deadline+",minutes:"+RainService.minutes+",mixAudio:"+RainService.mixAudio+",track:'"+RainService.track+"'})",null);handler.postDelayed(this,1000);}};
 public void onCreate(Bundle state){super.onCreate(state);Window window=getWindow();window.setStatusBarColor(android.graphics.Color.TRANSPARENT);window.setNavigationBarColor(0xff07110d);window.getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN);if(Build.VERSION.SDK_INT>=29)window.setNavigationBarContrastEnforced(false);web=new WebView(this);web.setBackgroundColor(0xff07110d);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.getSettings().setAllowFileAccess(true);web.setWebViewClient(new WebViewClient());web.setWebChromeClient(chrome);web.addJavascriptInterface(new Bridge(),"Android");web.loadUrl("file:///android_asset/index.html");if(Build.VERSION.SDK_INT>=33)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},1);}
 public void onResume(){super.onResume();web.onResume();handler.post(updates);}public void onPause(){handler.removeCallbacks(updates);web.onPause();super.onPause();}public void onDestroy(){handler.removeCallbacks(updates);web.destroy();web=null;super.onDestroy();}
 void command(String action,double value){Intent i=new Intent(this,RainService.class).setAction(action).putExtra("value",value);if(action.equals("play"))startForegroundService(i);else if(RainService.running)startService(i);}
 void setTimer(int minutes){Intent i=new Intent(this,RainService.class).setAction("timer").putExtra("value",minutes);startService(i);}
 class Bridge{@JavascriptInterface public int getStatusBarInsetDp(){int id=getResources().getIdentifier("status_bar_height","dimen","android");return id==0?24:Math.round(getResources().getDimensionPixelSize(id)/getResources().getDisplayMetrics().density);}@JavascriptInterface public String getTrack(){return RainService.track;}@JavascriptInterface public void setTrack(String id){if(!RainService.validTrack(id))return;if(RainService.running)startService(new Intent(MainActivity.this,RainService.class).setAction("track").putExtra("track",id));else RainService.track=id;}@JavascriptInterface public void play(){command("play",0);}@JavascriptInterface public void pause(){command("pause",0);}@JavascriptInterface public void setTimer(int m){RainService.minutes=m;MainActivity.this.setTimer(m);}@JavascriptInterface public void setMixAudio(boolean enabled){Intent i=new Intent(MainActivity.this,RainService.class).setAction("mixAudio").putExtra("value",enabled);if(RainService.running)startService(i);else getSharedPreferences("playback",0).edit().putBoolean("mixAudio",enabled).apply();RainService.mixAudio=enabled;}@JavascriptInterface public void setVolume(double v){RainService.volume=(float)v;command("volume",v);}@JavascriptInterface public void sync(){handler.post(()->web.evaluateJavascript("window.nativeState&&window.nativeState({playing:"+RainService.playing+",deadline:"+RainService.deadline+",minutes:"+RainService.minutes+",mixAudio:"+RainService.mixAudio+",track:'"+RainService.track+"'})",null));}}
}

